python -c "
import zipfile, xml.etree.ElementTree as ET
NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
# extract numeric values from expense rows C11:C22 and category labels from A11:A22
nums, cats = {}, {}
for row in root.findall('.//m:sheetData/m:row', NS):
    for c in row.findall('m:c', NS):
        r, t = c.get('r'), c.get('t')
        v, is_el = c.find('m:v', NS), c.find('m:is', NS)
        col = ''.join(ch for ch in r if ch.isalpha())
        if col == 'C' and v is not None and v.text:
            nums[r] = int(v.text)
        elif col == 'A' and t == 'inlineStr' and is_el is not None:
            cats[r] = ''.join(x.text or '' for x in is_el.findall('.//m:t', NS))
cat_totals = {}
for ref, val in nums.items():
    row_num = int(''.join(ch for ch in ref if ch.isdigit()))
    cat = cats.get(f'A{row_num}', 'Unknown')
    cat_totals[cat] = cat_totals.get(cat, 0) + val
for k, v in cat_totals.items():
    print(f'{k}: \${v}')
print('TOTAL EXPENSES: \$', sum(cat_totals.values()))
print('Cross-check SUM(C11:C22) from budget.xlsx =', sum(nums.values()))
"
